import sql from 'mssql';
import WHPLANT from './whplant.mjs';

const INV_GL = '32,33,38,41,42,43';

function getConfig() {
  return {
    user: process.env.MSSQL_USER || 'mcp_user',
    password: process.env.MSSQL_PASSWORD,
    server: process.env.MSSQL_SERVER || '203.202.241.211',
    port: parseInt(process.env.MSSQL_PORT || '1433', 10),
    database: process.env.MSSQL_DATABASE || 'DWH',
    options: {
      encrypt: false,
      trustServerCertificate: true,
      enableArithAbort: true
    },
    pool: { max: 5, min: 0, idleTimeoutMillis: 30000 },
    connectionTimeout: 6000,
    requestTimeout: 10000
  };
}

async function queryPool(pool, q) {
  const r = await pool.request().query(q);
  return r.recordset;
}

export async function fetchAll() {
  if (!process.env.MSSQL_PASSWORD) {
    throw new Error('MSSQL_PASSWORD env not configured');
  }
  const pool = await sql.connect(getConfig());
  try {
    const [stock, pr, aging, dio, clearance, whPlant, businessUnits, otif, space, manpower, approvalPending, movement, inventoryItems, peopleDesk] = await Promise.all([
      queryPool(pool, `SELECT TOP 40 bu.strBusinessUnit AS s, ISNULL(SUM(j.numAmount),0) AS v
        FROM saas.masterBusinessUnitArc bu
        LEFT JOIN fin.tblAccountingJournalArc j ON bu.intBusinessUnitId = j.intBusinessUnitId
          AND j.isActive=1 AND j.dteTransactionDate <= GETDATE() AND j.intGeneralLedgerId IN (${INV_GL})
        WHERE bu.isActive=1 AND bu.strBusinessUnit NOT LIKE '%Demo%'
        GROUP BY bu.strBusinessUnit
        HAVING ISNULL(SUM(j.numAmount),0) <> 0
        ORDER BY ISNULL(SUM(j.numAmount),0) DESC`),

      queryPool(pool, `SELECT TOP 15 h.strBusinessUnitName AS s,
          COUNT(DISTINCT h.intPurchaseRequestId) AS n,
          SUM(r.numRestQuantity) AS q,
          COUNT(DISTINCT r.strItemName) AS it,
          CONVERT(varchar, MAX(h.dteRequestDate), 23) AS d
        FROM pro.tblPurchaseRequestHeaderArc h
        JOIN pro.tblPurchaseRequestRowArc r ON h.intPurchaseRequestId = r.intPurchaseRequestId
        WHERE h.isActive=1 AND r.isActive=1 AND h.isComplete=0 AND h.strBusinessUnitName NOT LIKE '%Demo%'
        GROUP BY h.strBusinessUnitName
        ORDER BY SUM(r.numRestQuantity) DESC`),

      queryPool(pool, `SELECT bu.strBusinessUnit AS s,
          ISNULL(SUM(j.numAmount),0) AS v,
          DATEDIFF(DAY, MAX(j.dteTransactionDate), GETDATE()) AS d,
          CASE WHEN DATEDIFF(DAY, MAX(j.dteTransactionDate), GETDATE()) > 365 THEN 'Obsolete'
            WHEN DATEDIFF(DAY, MAX(j.dteTransactionDate), GETDATE()) >= 181 THEN 'Non-Moving'
            WHEN DATEDIFF(DAY, MAX(j.dteTransactionDate), GETDATE()) >= 91 THEN 'Slow-Moving'
            WHEN DATEDIFF(DAY, MAX(j.dteTransactionDate), GETDATE()) >= 31 THEN 'Moving'
            ELSE 'Fast-Moving' END AS c
        FROM saas.masterBusinessUnitArc bu
        LEFT JOIN fin.tblAccountingJournalArc j ON bu.intBusinessUnitId = j.intBusinessUnitId
          AND j.isActive=1 AND j.dteTransactionDate <= GETDATE() AND j.intGeneralLedgerId IN (${INV_GL})
        WHERE bu.isActive=1 AND bu.strBusinessUnit NOT LIKE '%Demo%'
        GROUP BY bu.strBusinessUnit
        HAVING MAX(j.dteTransactionDate) IS NOT NULL AND (DATEDIFF(DAY, MAX(j.dteTransactionDate), GETDATE()) > 90 OR ISNULL(SUM(j.numAmount),0) <> 0)`),

      queryPool(pool, `SELECT bu.strBusinessUnit AS s,
          SUM(CASE WHEN j.intGeneralLedgerId IN (${INV_GL}) THEN j.numAmount ELSE 0 END) AS inv,
          ABS(SUM(CASE WHEN ac.strAccountClassCode LIKE '4800000%' THEN j.numAmount ELSE 0 END)) AS cogs
        FROM fin.tblAccountingJournalArc j
        JOIN fin.tblGeneralLedgerArc gl ON j.intGeneralLedgerId = gl.intGeneralLedgerId
        JOIN fin.tblAccountCategoryArc cat ON gl.intAccountCategoryId = cat.intAccountCategoryId
        JOIN fin.tblAccountClassArc ac ON cat.intAccountClassId = ac.intAccountClassId
        JOIN saas.masterBusinessUnitArc bu ON j.intBusinessUnitId = bu.intBusinessUnitId
        WHERE j.isActive=1 AND bu.isActive=1 AND bu.strBusinessUnit NOT LIKE '%Demo%'
          AND j.dteTransactionDate >= '2026-01-01' AND j.dteTransactionDate <= GETDATE()
        GROUP BY bu.strBusinessUnit
        HAVING ABS(SUM(CASE WHEN ac.strAccountClassCode LIKE '4800000%' THEN j.numAmount ELSE 0 END)) > 0
        ORDER BY SUM(CASE WHEN j.intGeneralLedgerId IN (${INV_GL}) THEN j.numAmount ELSE 0 END) DESC`),

      queryPool(pool, `SELECT TOP 40 strBusinessUnitName AS s, COUNT(*) AS c, ISNULL(SUM(numLastMonthSalary),0) AS sal
        FROM saas.EmpClearanceApplicationArc
        WHERE isActive=1 AND (strStatus='Pending' OR strStatus IS NULL)
        GROUP BY strBusinessUnitName
        ORDER BY COUNT(*) DESC`),

      queryPool(pool, `SELECT DISTINCT strBusinessUnitName AS bu, strWarehouseName AS wh, strPlantName AS plant
        FROM wms.tblPlantWarehouseArc
        WHERE isActive=1 AND strBusinessUnitName IS NOT NULL AND strBusinessUnitName NOT LIKE '%Demo%'
          AND strWarehouseName IS NOT NULL AND strPlantName IS NOT NULL
        ORDER BY strBusinessUnitName, strWarehouseName, strPlantName`),

      queryPool(pool, `SELECT strBusinessUnit AS s
        FROM saas.masterBusinessUnitArc
        WHERE strBusinessUnit NOT LIKE '%Demo%' AND strBusinessUnit IS NOT NULL AND strBusinessUnit <> ''
        ORDER BY strBusinessUnit`),

      queryPool(pool, `SELECT TOP 15 strBusinessUnitName AS sbu,
          COUNT(*) AS sos,
          SUM(CASE WHEN dteDueShippingDate IS NOT NULL THEN 1 ELSE 0 END) AS withDate,
          SUM(CASE WHEN isCompleted=1 THEN 1 ELSE 0 END) AS completed
        FROM oms.tblSalesOrderHeaderArc
        WHERE isActive=1 AND strBusinessUnitName NOT LIKE '%Demo%' AND strBusinessUnitName IS NOT NULL
          AND dteSalesOrderDate >= DATEADD(day,-90,GETDATE())
        GROUP BY strBusinessUnitName
        ORDER BY COUNT(*) DESC`),

      queryPool(pool, `SELECT TOP 15 strBusinessUnitName AS sbu, strWareHouseName AS wh, strPlantName AS plant,
          COUNT(*) AS items, SUM(numCurrentStock) AS currentStock, SUM(ABS(numCurrentStock)) AS absStock
        FROM wms.tblItemPlantWarehouseArc
        WHERE isActive=1 AND strBusinessUnitName NOT LIKE '%Demo%' AND strBusinessUnitName IS NOT NULL
        GROUP BY strBusinessUnitName, strWareHouseName, strPlantName
        ORDER BY SUM(ABS(numCurrentStock)) DESC`),

      queryPool(pool, `SELECT TOP 15 bu.strBusinessUnit AS sbu, COUNT(e.intEmployeeBasicInfoId) AS empCount
        FROM saas.empEmployeeBasicInfoArc e
        LEFT JOIN saas.masterBusinessUnitArc bu ON e.intBusinessUnitId = bu.intBusinessUnitId
        WHERE e.isActive=1 AND bu.strBusinessUnit NOT LIKE '%Demo%' AND bu.strBusinessUnit IS NOT NULL
        GROUP BY bu.strBusinessUnit
        ORDER BY COUNT(e.intEmployeeBasicInfoId) DESC`),

      queryPool(pool, `SELECT TOP 15 h.strBusinessUnitName AS sbu, COUNT(DISTINCT h.intPurchaseRequestId) AS prs, SUM(r.numRequestQuantity) AS qty
        FROM pro.tblPurchaseRequestHeaderArc h JOIN pro.tblPurchaseRequestRowArc r ON h.intPurchaseRequestId=r.intPurchaseRequestId
        WHERE h.isActive=1 AND r.isActive=1 AND h.isApproved=0 AND (h.isRejected=0 OR h.isRejected IS NULL) AND h.isComplete=0
          AND h.strBusinessUnitName NOT LIKE '%Demo%' AND h.strBusinessUnitName IS NOT NULL
        GROUP BY h.strBusinessUnitName
        ORDER BY COUNT(DISTINCT h.intPurchaseRequestId) DESC`),

      queryPool(pool, `SELECT CONVERT(varchar(10), h.dteTransactionDate, 23) AS dte, h.strBusinessUnitName AS sbu,
          h.strPlantName AS plant, h.strWarehouseName AS wh,
          SUM(CASE WHEN h.TransactionGroupName IN ('Receive Inventory','Received From Production','Service Receive','Asset Receive','Transfer In','Received From Customer','Issue Return') THEN r.numTransactionQuantity ELSE 0 END) AS r,
          SUM(CASE WHEN h.TransactionGroupName IN ('Issue Inventory','Transfer Out','Purchase Return') THEN ABS(r.numTransactionQuantity) ELSE 0 END) AS i,
          SUM(r.numTransactionQuantity) AS n
        FROM wms.tblInventoryTransactionHeaderArc h
        JOIN wms.tblInventoryTransactionRowArc r ON h.intInventoryTransactionId = r.intInventoryTransactionId
        WHERE h.isActive=1 AND r.isActive=1 AND h.strBusinessUnitName NOT LIKE '%Demo%' AND h.strBusinessUnitName IS NOT NULL
          AND h.dteTransactionDate >= DATEADD(day,-120,GETDATE())
        GROUP BY CONVERT(varchar(10), h.dteTransactionDate, 23), h.strBusinessUnitName, h.strPlantName, h.strWarehouseName
        ORDER BY dte`),

      queryPool(pool, `SELECT TOP 2000 i.strItemCode AS sku, i.strItemName AS itemDescription, ISNULL(i.strItemCategoryName,'') AS category, ISNULL(i.strItemTypeName,'') AS inventoryType,
          pw.strBusinessUnitName AS sbu, pw.strWareHouseName AS warehouse, pw.numCurrentStock AS quantity, i.numAverageRate AS unitCost,
          ROUND(pw.numCurrentStock * i.numAverageRate,2) AS stockValue,
          CONVERT(varchar(10), pw.dteLastActionDateTime, 23) AS lastMovementDate,
          DATEDIFF(day, pw.dteLastActionDateTime, GETDATE()) AS ageDays
        FROM wms.tblItemPlantWarehouseArc pw
        JOIN itm.tblItemArc i ON pw.intItemId = i.intItemId
        WHERE pw.isActive=1 AND i.isActive=1 AND pw.strBusinessUnitName NOT LIKE '%Demo%' AND pw.strBusinessUnitName IS NOT NULL
          AND pw.numCurrentStock <> 0
        ORDER BY ABS(pw.numCurrentStock * i.numAverageRate) DESC`),

      queryPool(pool, `SELECT
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1) AS activeEmployees,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strEmploymentType='Permanent') AS permanent,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strEmploymentType='Probationary') AS probationary,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strEmploymentType='Contractual') AS contractual,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strEmploymentType='Casual') AS casual,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strEmploymentType='Intern') AS interns,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strGender='Male') AS male,
          (SELECT COUNT(*) FROM saas.empEmployeeBasicInfoArc WHERE isActive=1 AND strGender='Female') AS female,
          (SELECT COUNT(*) FROM saas.EmpClearanceApplicationArc WHERE isActive=1 AND (strStatus IS NULL OR strStatus='')) AS clearancePending,
          (SELECT ISNULL(SUM(numLastMonthSalary),0) FROM saas.EmpClearanceApplicationArc WHERE isActive=1 AND (strStatus IS NULL OR strStatus='')) AS clearanceSalary`)
    ]);

    return {
      generatedAt: new Date().toISOString(),
      stock,
      pr,
      aging,
      dio,
      clearance,
      whPlant,
      businessUnits,
      otif,
      space,
      manpower,
      approvalPending,
      movement,
      inventoryItems,
      peopleDesk
    };
  } finally {
    await pool.close();
  }
}

